-- GÉNÉRÉ par scripts/generer-seed.mjs depuis data/signes-depart.json — ne pas éditer à la main.
-- 803 signes. Exécuter après les migrations (0001 à 0004). Relançable (upsert sur glose).
on conflict (glose) do update set
  mots_fr = excluded.mots_fr,
  categorie = excluded.categorie,
  type = excluded.type,
  priorite = excluded.priorite,
  notes = excluded.notes,
  definition = excluded.definition,
  reference_url = excluded.reference_url;
